async function compressPhoto(file) {
  if (!(file instanceof File) || !file.type.startsWith('image/')) throw new Error('ატვირთე გამოსახულების ფაილი.');
  if (file.size > 12 * 1024 * 1024) throw new Error('ფოტოს ზომა 12 მბ-ს არ უნდა აღემატებოდეს.');
  const bitmap = await createImageBitmap(file);
  const scale = Math.min(1, 1100 / Math.max(bitmap.width, bitmap.height));
  const canvas = document.createElement('canvas');
  canvas.width = Math.round(bitmap.width * scale);
  canvas.height = Math.round(bitmap.height * scale);
  const context = canvas.getContext('2d');
  if (!context) throw new Error('ფოტოს დამუშავება ვერ მოხერხდა.');
  context.fillStyle = '#0F1115';
  context.fillRect(0, 0, canvas.width, canvas.height);
  context.drawImage(bitmap, 0, 0, canvas.width, canvas.height);
  bitmap.close();
  return new Promise((resolve, reject) => {
    canvas.toBlob(blob => {
      if (!blob) { reject(new Error('ფოტოს დამუშავება ვერ მოხერხდა.')); return; }
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result);
      reader.onerror = () => reject(new Error('ფოტოს დამუშავება ვერ მოხერხდა.'));
      reader.readAsDataURL(blob);
    }, 'image/jpeg', 0.72);
  });
}

