function localizeTree(root = document) {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  nodes.forEach(node => {
    const key = node.nodeValue.trim();
    if (localeLookup[key]) node.nodeValue = node.nodeValue.replace(key, localeLookup[key][state.language]);
  });
  root.querySelectorAll?.('[placeholder], [aria-label], [title]').forEach(element => {
    ['placeholder', 'aria-label', 'title'].forEach(attribute => {
      const value = element.getAttribute(attribute);
      if (value && localeLookup[value]) element.setAttribute(attribute, localeLookup[value][state.language]);
    });
  });
}
