function openModal(title, body, extraClass = '') {
  if (!modalRoot) return;
  chatRequestToken += 1;
  if (chatMessagesUnsubscribe) {
    chatMessagesUnsubscribe();
    chatMessagesUnsubscribe = null;
  }
  if (orderHistoryUnsubscribe) {
    orderHistoryUnsubscribe();
    orderHistoryUnsubscribe = null;
  }
  if (productReviewsUnsubscribe) {
    productReviewsUnsubscribe();
    productReviewsUnsubscribe = null;
  }
  modalRoot.innerHTML = `<div class="modal-backdrop" data-close-modal><section class="modal ${extraClass}" role="dialog" aria-modal="true" aria-label="${escapeHTML(title)}"><button class="modal-close" type="button" data-close-modal aria-label="ფანჯრის დახურვა">×</button><div class="modal-content"><p class="eyebrow">DROPZONE / MARKET</p><h2>${title}</h2>${body}</div></section></div>`;
  localizeTree(modalRoot);
  const businessFields = modalRoot.querySelector('#auth-business-fields');
  if (businessFields && !businessFields.querySelector('[name="phone"]')) {
    const phoneField = document.createElement('label');
    phoneField.className = 'field-label';
    phoneField.innerHTML = `${escapeHTML(tr('ტელეფონი'))}<input name="phone" type="tel" placeholder="+995 5XX XX XX XX">`;
    businessFields.prepend(phoneField);
  }
  document.body.classList.add('modal-open');
  modalRoot.querySelector('.modal-close')?.focus();
}
