document.addEventListener('click', event => {
  if (event.target.closest('[data-open-admin]')) { adminLoginModal(); return; }
  const approvalButton = event.target.closest('[data-admin-approve], [data-admin-reject]');
  if (approvalButton && adminUnlocked) {
    const id = approvalButton.dataset.adminApprove || approvalButton.dataset.adminReject;
    const product = allProducts.find(item => String(item.id) === id);
    if (product?.approvalStatus === 'Pending') {
      product.approvalStatus = approvalButton.hasAttribute('data-admin-approve') ? 'Approved' : 'Rejected';
      saveAdminListings();
      adminPanel();
    }
    return;
  }
  const editButton = event.target.closest('[data-admin-edit]');
  if (editButton && adminUnlocked) { adminEditProduct(editButton.dataset.adminEdit); return; }
  const deleteButton = event.target.closest('[data-admin-delete]');
  if (deleteButton && adminUnlocked) {
    const id = deleteButton.dataset.adminDelete;
    allProducts.splice(0, allProducts.length, ...allProducts.filter(product => String(product.id) !== id));
    state.userProducts = state.userProducts.filter(product => String(product.id) !== id);
    state.favorites = state.favorites.filter(favorite => String(favorite) !== id);
    state.cart = state.cart.filter(item => String(item.id) !== id);
    saveState();
    saveAdminListings();
    adminPanel();
    return;
  }
  const verifyButton = event.target.closest('[data-admin-verify]');
  if (verifyButton && adminUnlocked) {
    const product = allProducts.find(item => String(item.id) === verifyButton.dataset.adminVerify);
    if (product) product.verified = !isVerifiedProduct(product);
    saveAdminListings();
    adminPanel();
  }
  const banButton = event.target.closest('[data-admin-ban]');
  if (banButton && adminUnlocked) {
    const user = users[Number(banButton.dataset.adminBan)];
    if (user) {
      user.banned = !user.banned;
      if (currentUser()?.email === user.email) storage.write('dz-user', { ...currentUser(), banned: user.banned });
      storage.write('dz-users', users);
    }
    adminPanel();
  }
  const userVerifyButton = event.target.closest('[data-admin-user-verify]');
  if (userVerifyButton && adminUnlocked) {
    const user = users[Number(userVerifyButton.dataset.adminUserVerify)];
    if (user) {
      user.verified = !user.verified;
      allProducts.filter(product => product.sellerId === user.email).forEach(product => { product.verified = user.verified; });
      if (currentUser()?.email === user.email) storage.write('dz-user', { ...currentUser(), verified: user.verified });
      storage.write('dz-users', users);
      saveAdminListings();
    }
    adminPanel();
  }
  const payoutButton = event.target.closest('[data-admin-payout]');
  if (payoutButton && adminUnlocked) {
    const request = payoutRequests.find(item => item.id === payoutButton.dataset.adminPayout);
    if (request) { request.status = 'approved'; recordTransaction('payout', -request.amount, { email: request.email, reference: request.id }); }
    adminPanel();
  }
  const paymentButton = event.target.closest('[data-admin-payment-approve], [data-admin-payment-reject]');
  if (paymentButton && adminUnlocked) {
    const requestId = paymentButton.dataset.adminPaymentApprove || paymentButton.dataset.adminPaymentReject;
    const request = paymentRequests.find(item => item.id === requestId);
    if (!request || request.status !== 'pending') {
      showToast(tr('ეს გადახდის მოთხოვნა უკვე დამუშავებულია.'));
      adminPanel();
      return;
    }
    try {
      if (paymentButton.hasAttribute('data-admin-payment-approve')) approvePaymentRequest(request);
      else {
        request.status = 'rejected';
        request.reviewedAt = new Date().toISOString();
      }
      localStorage.setItem('dz-payment-requests', JSON.stringify(paymentRequests));
      saveFinance();
      updateHeader();
      adminPanel();
    } catch (error) {
      request.status = 'pending';
      showToast(error.message || tr('მოთხოვნის დამუშავება ვერ მოხერხდა.'));
      adminPanel();
    }
    return;
  }
});
